# mesurments: общая шапка карточек, составной как обычный размер, перестановка
import pathlib,re,json
exec(open(pathlib.Path(__file__).with_name('browser.py')).read().split('with sync_playwright() as p:')[0])
with sync_playwright() as p:
    b=p.chromium.launch();ctx=b.new_context(accept_downloads=True,viewport={'width':1500,'height':900});ctx.route('**/*',route);errors=[]
    def page(path):
        g=ctx.new_page();g.on('pageerror',lambda e:errors.append(f'{path.name}: {e}'));g.on('dialog',lambda d:d.accept());g.goto(path.as_uri());g.wait_for_timeout(1200)
        # Tailwind с CDN в тестах закрыт — подставляем собранные локально стили, чтобы панель выглядела по-настоящему
        css=pathlib.Path('/tmp/claude-0/-home-claude/a99286d1-0140-584d-91cc-85669ffe407b/scratchpad/tw.css')
        if path.name=='mesurments.html' and css.exists():g.add_style_tag(path=str(css));g.wait_for_timeout(300)
        return g
    def export(g,name):
        with g.expect_download(timeout=15000) as d:g.locator('#btn-export-html').evaluate('el=>el.click()')
        f=T/name;d.value.save_as(f);return f
    def data(f):return json.loads(re.search(r'id="__CAD_ANNOTATIONS_DATA__"[^>]*>(.*?)</script>',f.read_text(),re.S).group(1))
    def click(loc):loc.evaluate('el=>el.click()');loc.page.wait_for_timeout(300)
    def put(loc,v,ev='change'):loc.evaluate('(el,[v,ev])=>{if(el.type==="checkbox")el.checked=v;else el.value=v;el.dispatchEvent(new Event(ev,{bubbles:true}))}',[v,ev]);loc.page.wait_for_timeout(300)
    e=page(OUT/'mesurments.html');e.set_input_files('#file-input',str(T/'project-set.html'));e.wait_for_timeout(1500)
    cards=e.locator('#dimensions-list > [data-card-id]')
    NAMES='()=>[...document.querySelectorAll("#dimensions-list > [data-card-id]")].map(c=>c.querySelector("[data-action=name]").value)'
    names=lambda g=e:g.evaluate(NAMES)
    base=names();ok('старый проект открывается',cards.count()==4,base)
    W,S1,ST,S2=base
    def card(n,g=e):return g.locator('#dimensions-list > [data-card-id]').nth(names(g).index(n))
    def A(n,a,g=e):return card(n,g).locator(f'[data-action="{a}"]')
    print('Составной размер')
    click(e.locator('#btn-comp-add'));N='Паз и стенка';c=e.locator('[data-comp-card]')
    put(c.locator('[data-action="name"]'),N,'input')
    ok('создаётся фиолетовым и вверху списка',c.locator('[data-action="color"]').input_value()=='#8b5cf6' and names()[0]==N,names())
    acts=lambda x:x.evaluate('c=>[...c.querySelectorAll("[data-action]")].map(e=>e.dataset.action)')
    head=['color','collapse','exclusive','precision','toggle','delete','param','up','down']
    ok('шапка та же, что у обычной карточки',acts(c)[:9]==head and acts(card(W))[:9]==head,(acts(c)[:9],acts(card(W))[:9]))
    ok('в списке все размеры, отметок пока нет',c.locator('[data-member]').count()==4 and c.locator('[data-member]:checked').count()==0)
    for n in [S1,ST]:put(c.locator('label').filter(has=e.get_by_text(n,exact=True)).locator('input'),True)
    ok('отмечены паз и стенка',c.locator('[data-member]:checked').count()==2)
    a=acts(c);need=['refon','limit','amin','amax','showscale','sync','prop','anchor']
    ok('ниже те же настройки, что у размера, в том же порядке',[x for x in a if x in need]==need and [x for x in acts(card(W)) if x in need]==need,a)
    click(c.locator('[data-action="collapse"]'))
    ok('свёрнутый составной: шапка с «Ползунок в конвертере» и название',c.evaluate('c=>c.children.length')==2 and c.locator('[data-action="param"]').is_visible() and 'Ползунок в конвертере' in c.inner_text() and c.locator('[data-action="name"]').is_visible() and c.locator('[data-member]').count()==0,c.inner_text())
    click(A(W,'collapse'));ok('у свёрнутого обычного размера галочка ползунка видна',A(W,'param').is_visible() and A(W,'limit').count()==0)
    put(A(W,'param'),False);ok('в свёрнутой карточке она переключается и не разворачивает',not A(W,'param').is_checked() and A(W,'limit').count()==0)
    put(A(W,'param'),True)
    click(A(W,'collapse'));click(c.locator('[data-action="collapse"]'))
    put(c.locator('[data-action="color"]'),'#ff0000','input')
    ok('цвет меняет рамку и пометки',c.evaluate('c=>c.style.borderColor')=='rgb(255, 0, 0)' and e.locator('[data-comp-note]').nth(0).evaluate('n=>n.style.borderColor')=='rgb(255, 0, 0)')
    put(c.locator('[data-action="color"]'),'#8b5cf6','input')
    put(c.locator('[data-action="precision"]'),'1');ok('точность составного','54.0 мм = 42.0 + 12.0' in c.inner_text(),c.inner_text())
    EY='()=>annotations_vis()'
    click(c.locator('[data-action="toggle"]'));hidden=data(export(e,'cards-eye.html'))['annotations']
    ok('глаз скрывает входящие размеры',[x['visible'] for x in hidden]==[True,False,False,True],[x['visible'] for x in hidden])
    click(c.locator('[data-action="toggle"]'));ok('и показывает обратно',all(x['visible'] for x in data(export(e,'cards-eye.html'))['annotations']))
    put(c.locator('[data-action="limit"]'),'pct');ok('лимит в %: 50–200',c.locator('[data-action="pmin"]').input_value()=='50' and c.locator('[data-action="pmax"]').input_value()=='200')
    put(c.locator('[data-action="pmin"]'),'80');put(c.locator('[data-action="pmax"]'),'150')
    put(c.locator('[data-action="refon"]'),True)
    opts=c.locator('[data-action="refsel"] option').all_inner_texts();ok('ограничить можно только не входящими',len(opts)==2 and opts[0].startswith(W) and opts[1].startswith(S2),opts)
    put(c.locator('[data-action="refval"]'),'0.6');ok('формула и «≤»','≤ 72.0' in c.inner_text(),c.inner_text())
    put(c.locator('[data-action="sync"]'),'new');put(c.locator('[data-action="gname"]'),'Карман','input');put(c.locator('[data-action="gname"]'),'Карман')
    g=c.locator('[data-action="sync"]').input_value();ok('новая группа синхронизации',g!='0')
    put(A(S1,'sync'),g);ok('входящий размер в ту же группу не добавить',A(S1,'sync').input_value()=='0',A(S1,'sync').input_value())
    put(A(S2,'sync'),g);ok('посторонний размер входит в группу составного',A(S2,'sync').input_value()==g and A(S2,'param').is_checked() and not c.locator('[data-action="param"]').is_checked(),(A(S2,'param').is_checked(),c.locator('[data-action="param"]').is_checked()))
    put(c.locator('[data-action="param"]'),True)
    put(c.locator('[data-action="prop"]'),'new');pg=c.locator('[data-action="prop"]').input_value();ok('пропорциональная группа',pg!='0')
    put(c.locator('[data-action="prop"]'),'0')
    put(c.locator('[data-action="anchor"]'),'1');ok('направление задано входящим',A(S1,'anchor').input_value()=='1' and A(ST,'anchor').input_value()=='1' and A(W,'anchor').input_value()!='1',(A(S1,'anchor').input_value(),A(W,'anchor').input_value()))
    put(A(ST,'anchor'),'2');ok('разные направления — «своё у каждого»',c.locator('[data-action="anchor"]').input_value()=='')
    put(A(ST,'anchor'),'1')
    put(card(ST).locator('[data-action="amax"]'),'20');ok('пределы входящих сразу пересчитываются','от' in c.inner_text() and c.locator('[data-action="pmax"]').count()==1)
    print('Перестановка')
    ok('у крайних стрелки выключены',cards.first.locator('[data-action="up"]').is_disabled() and cards.last.locator('[data-action="down"]').is_disabled())
    click(A(N,'down'));click(A(N,'down'));ok('стрелка ▼ переносит составной ниже',names()==[W,S1,N,ST,S2],names())
    click(A(S2,'up'));ok('стрелка ▲ переносит размер выше',names()==[W,S1,N,S2,ST],names())
    for n in [W,S1,N]:
        x=A(n,'collapse')
        if x.inner_text().strip()=='▾':click(x)
    e.locator('#dimensions-list').evaluate('l=>l.scrollTop=0');e.wait_for_timeout(300)
    h=card(S1).locator('.mvh').bounding_box();t=card(W).bounding_box()
    e.mouse.move(h['x']+h['width']/2,h['y']+h['height']/2);e.mouse.down();e.mouse.move(h['x'],t['y']+4,steps=12);e.mouse.up();e.wait_for_timeout(400)
    order=[S1,W,N,S2,ST];ok('перетаскивание за ⠿',names()==order,names())
    for n in order:
        x=card(n).locator('[data-action="collapse"]')
        if x.inner_text().strip()=='▾':click(x)
    ok('все свёрнуты: у каждой видна галочка ползунка',e.locator('#dimensions-list [data-action="param"]').count()==5 and all(e.locator('#dimensions-list [data-action="param"]').nth(i).is_visible() for i in range(5)))
    e.mouse.move(5,500);e.screenshot(path=str(T/'mes-cards.png'))
    click(A(N,'collapse'));e.screenshot(path=str(T/'mes-cards-open.png'))
    prj=export(e,'cards.html');d=data(prj);cm=d['composites'][0]
    ok('в файл ушли настройки составного',[cm[k] for k in ('limit','pmin','pmax','limRef','limOp','limVal','syncName','precision','param','color')]==['pct',80,150,0,'*',0.6,'Карман',1,False,'#f59e0b'] and cm['syncGroup']==int(g),cm)
    ok('в файл ушёл порядок',d['order']==['a1','a0','c0','a3','a2'],d.get('order'))
    print('Повторное открытие')
    e2=page(OUT/'mesurments.html');e2.set_input_files('#file-input',str(prj));e2.wait_for_timeout(1500)
    ok('порядок восстановлен',names(e2)==order,names(e2))
    d2=data(export(e2,'cards2.html'));ok('повторное сохранение даёт то же самое',d2['composites']==d['composites'] and d2['order']==d['order'],(d2['composites'],d2['order']))
    c2=e2.locator('[data-comp-card]')
    if c2.locator('[data-action="limit"]').count()==0:click(c2.locator('[data-action="collapse"]'))
    ok('настройки видны в карточке',c2.locator('[data-action="pmin"]').input_value()=='80' and c2.locator('[data-action="refon"]').is_checked() and c2.locator('[data-action="sync"]').input_value()!='0' and c2.locator('[data-action="gname"]').input_value()=='Карман')
    put(c2.locator('[data-action="exclusive"]'),True);click(c2.locator('[data-comp-badge]'))
    click(card(W,e2).locator('[data-action="collapse"]'))
    ok('авто-сворачивание действует и на составной',c2.locator('[data-member]').count()==0 and card(W,e2).locator('[data-action="limit"]').count()==1)
    click(card(S2,e2).locator('[data-action="delete"]'));ok('удаление размера не ломает порядок',names(e2)==[S1,W,N,ST],names(e2))
    click(card(W,e2).locator('[data-action="delete"]'));ok('удалённый размер-ограничитель снимает ограничение',data(export(e2,'cards2.html'))['composites'][0]['limRef']==-1)
    click(c2.locator('[data-comp-badge]'));e2.keyboard.press('Delete');e2.wait_for_timeout(300);ok('клавиша Delete удаляет выбранный составной',e2.locator('[data-comp-card]').count()==0 and names(e2)==[S1,ST],names(e2))
    print('Конвертер')
    c=page(OUT/'Конвертер-OBJ-HTML.html');c.set_input_files('#f',str(prj));c.wait_for_timeout(2000)
    ks=c.evaluate('()=>plist().map(p=>p.key)');ok('порядок ползунков как в редакторе',ks==['sc','q1','q0','c0','q3','q2'] or ks==['sc','q1','q0','c0','q2'],ks)
    s=c.evaluate('()=>st.cm[0]');ok('конвертер получил настройки составного',s.get('lm')=='pct' and s.get('rf')==0 and s.get('rval')==0.6 and s.get('g')==int(g) and s.get('gn')=='Карман' and abs(s['mn']-43.2)<.01 and abs(s['mx']-81)<.01,s)
    ok('снятая в редакторе галочка составного скрывает его ползунок в конвертере',c.locator('#axes .row[data-key="c0"].off').count()==1 and not c.locator('#axes .row[data-key="c0"] .h input[type=checkbox]').first.is_checked())
    ok('нет ошибок JavaScript',not errors,errors[:5])
    b.close()
print(f'\nИтого: пройдено {ok_n}, ошибок {bad_n}')
